var cache = new ConditionalWeakTable<Session, Expensive>();
var session = new Session();
cache.Add(session, new Expensive());        // the key, not the value, is weak

var weak = new WeakReference<Session>(session);
if (weak.TryGetTarget(out var alive))       // promotion; false once collected
    alive.RoundTrip();
// session = null; GC.Collect(); TryGetTarget then returns false
